    uint16 affiliateDiscount; //BPS
    uint16 defaultRoyalty; //BPS
}

// allocation splits for withdrawn owner funds, must sum to 100%
struct PayoutConfig {
    uint16 ownerBps;
    uint16 platformBps;
    uint16 partnerBps;
    uint16 superAffiliateBps;
    address partner;
    address superAffiliate;
    address ownerAltPayout;
}

