}

struct BurnInvite {
    IERC721 burnErc721;
    address burnAddress;
    address tokenAddress;
    uint128 price; // flat price - does not support discounts
    bool reversed; // side of the ratio (false=burn {ratio} get 1, true=burn 1 get {ratio})
    uint16 ratio;
    uint32 start;
    uint32 end;
    uint64 limit;
}

struct ValidationArgs {
    address owner;
    address affiliate;
    uint256 quantity;
    uint256 curSupply;
